import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"Flow per Webhook starten","description":"Einen Flow von einem fremden System aus auslösen.","frontmatter":{"title":"Flow per Webhook starten","description":"Einen Flow von einem fremden System aus auslösen."},"headers":[],"relativePath":"flows/webhook-trigger.md","filePath":"flows/webhook-trigger.md","lastUpdated":1786170655000}'),s={name:"flows/webhook-trigger.md"};function a(o,e,l,h,d,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="flow-per-webhook-starten" tabindex="-1">Flow per Webhook starten <a class="header-anchor" href="#flow-per-webhook-starten" aria-label="Permalink to &quot;Flow per Webhook starten&quot;">​</a></h1><p>Der Auslöser <strong>Webhook</strong> startet einen Flow, wenn ein fremdes System eine Anfrage schickt. Damit binden Sie ApptiveGrid an beliebige andere Werkzeuge an.</p><div class="tip custom-block"><p class="custom-block-title">Nicht mit ausgehenden Webhooks verwechseln</p><table tabindex="0"><thead><tr><th>Richtung</th><th>Wo eingerichtet</th></tr></thead><tbody><tr><td><strong>Fremdsystem → ApptiveGrid</strong></td><td>Flow-Auslöser <em>Webhook</em> — diese Seite</td></tr><tr><td><strong>ApptiveGrid → Fremdsystem</strong></td><td><a href="/integrationen/webhooks">Webhooks</a> in den Space-Einstellungen</td></tr></tbody></table></div><h2 id="einrichten" tabindex="-1">Einrichten <a class="header-anchor" href="#einrichten" aria-label="Permalink to &quot;Einrichten&quot;">​</a></h2><ol><li>Legen Sie einen neuen Flow an.</li><li>Wählen Sie im Reiter <strong>Auslöser</strong> den Eintrag <strong>Webhook</strong>.</li><li>Öffnen Sie den Schritt — dort steht die Adresse.</li></ol><p>Der Abschnitt heißt <strong>Link zum Starten des Flows</strong>:</p><blockquote><p><em>Um den Flow zu starten, senden Sie eine POST-Request an die folgende URL:</em></p></blockquote><h2 id="daten-ubergeben" tabindex="-1">Daten übergeben <a class="header-anchor" href="#daten-ubergeben" aria-label="Permalink to &quot;Daten übergeben&quot;">​</a></h2><p><strong>POST-Request senden</strong></p><blockquote><p><em>Senden Sie Daten im JSON-Format per POST-Request an den obigen Link, um den Flow zu starten.</em></p></blockquote><p>Die übergebenen JSON-Daten stehen allen folgenden Schritten zur Verfügung. → <a href="/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></p><h2 id="in-einem-fremden-system-eintragen" tabindex="-1">In einem fremden System eintragen <a class="header-anchor" href="#in-einem-fremden-system-eintragen" aria-label="Permalink to &quot;In einem fremden System eintragen&quot;">​</a></h2><p><strong>Als Webhook verwenden</strong></p><blockquote><p><em>Tragen Sie die URL als Webhook bei anderen Services ein. Dadurch wird der Workflow automatisch gestartet, wenn der entsprechende Service den Webhook auslöst.</em></p></blockquote><p>Praktisch überall dort, wo ein Dienst „Webhook-URL&quot; abfragt — Formulardienste, Shopsysteme, Zahlungsanbieter, Automatisierungsplattformen, Überwachungswerkzeuge.</p><h2 id="testen" tabindex="-1">Testen <a class="header-anchor" href="#testen" aria-label="Permalink to &quot;Testen&quot;">​</a></h2><p><strong>Webhook testen</strong></p><blockquote><p><em>Sie können den Webhook testen, indem Sie einen Beispiel-JSON-Payload senden:</em></p></blockquote><p>Tragen Sie unter <strong>JSON-Payload</strong> Beispieldaten ein und klicken Sie <strong>Jetzt testen</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Mit echten Daten testen</p><p>Nehmen Sie als Beispiel-Payload möglichst genau das, was das fremde System tatsächlich schickt. Viele Dienste zeigen in ihrer Oberfläche ein Beispiel — kopieren Sie es hierher.</p><p>Sonst bauen Sie den Flow gegen eine ausgedachte Struktur und er scheitert beim ersten echten Aufruf.</p></div><p>Alternativ steht im Editor <strong>Mit Test-Daten starten</strong> zur Verfügung: <em>Gib Beispiel-Daten an</em>.</p><p>→ <a href="/flows/testen">Flows testen</a></p><h2 id="sicherheit" tabindex="-1">Sicherheit <a class="header-anchor" href="#sicherheit" aria-label="Permalink to &quot;Sicherheit&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Die Webhook-URL ist ein Zugang</p><p>Wer die Adresse kennt, kann den Flow starten — beliebig oft. Es gibt keine zusätzliche Prüfung, wer die Anfrage schickt.</p><p>Behandeln Sie sie wie ein Passwort:</p><ul><li>nicht in öffentliche Repositories</li><li>nicht in Chats oder auf Folien</li><li>nur im Zielsystem hinterlegen</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Bedenken Sie, was der Flow tut</p><p>Ein Flow, der Einträge anlegt oder E-Mails verschickt, tut das bei jedem Aufruf. Gelangt die URL in falsche Hände oder ruft ein fehlerhaftes System sie wiederholt auf, entstehen entsprechend viele Vorgänge.</p><p>Prüfen Sie im <a href="/flows/durchlaufhistorie">Verlauf</a> regelmäßig, ob die Anzahl der Ausführungen plausibel ist.</p></div><p>Alle aktiven Zugänge eines Space stehen unter <a href="/zusammenarbeit/externe-links">Externe Links im Überblick</a> — der Typ heißt dort <strong>Flow starten</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Nicht mehr benötigte Webhooks entfernen</p><p>Ein Webhook bleibt aktiv, solange der Flow existiert — auch wenn das anbindende System längst abgeschaltet ist. Gehen Sie die Links-Übersicht regelmäßig durch.</p></div><h2 id="typische-anwendungen" tabindex="-1">Typische Anwendungen <a class="header-anchor" href="#typische-anwendungen" aria-label="Permalink to &quot;Typische Anwendungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anwendung</th><th>Ablauf</th></tr></thead><tbody><tr><td>Bestellung aus einem Shop übernehmen</td><td>Shop ruft Webhook, Flow legt Eintrag an</td></tr><tr><td>Formular eines Fremdanbieters verarbeiten</td><td>Dienst ruft Webhook, Flow verteilt die Daten</td></tr><tr><td>Störungsmeldung aus einem Überwachungssystem</td><td>System ruft Webhook, Flow benachrichtigt und protokolliert</td></tr><tr><td>Nächtlicher Import aus einem anderen System</td><td>Skript ruft Webhook mit Daten</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Keine zeitgesteuerte Auslösung</p><p>ApptiveGrid kennt keinen Auslöser „jeden Tag um 8 Uhr&quot;. Wollen Sie einen Flow regelmäßig starten, muss ein externes System die Webhook-URL zum gewünschten Zeitpunkt aufrufen.</p><p>Der Schritt <strong>Warten</strong> hilft dabei nicht: Er misst ab dem Erreichen des Schritts, nicht bis zu einem festen Zeitpunkt. → <a href="/flows/router-und-parallel">Router und Parallel</a></p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/flows/trigger">Trigger</a></li><li><a href="/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></li><li><a href="/zusammenarbeit/externe-links">Externe Links im Überblick</a></li></ul>',32)])])}const g=t(s,[["render",a]]);export{b as __pageData,g as default};
